3445	    /// Perform a raw bulk-memory-like libcall.
3446	    ///
3447	    /// The main purpose of this helper is to handle situations when fuel and
3448	    /// epochs are enabled to break up the copy into a loop of chunks with
3449	    /// preemption checks between them.
3450	    fn raw_bulk_memory_operation(&mut self, builder: &mut FunctionBuilder<'_>, mut op: BulkOp) {
3451	        // Very scientifically chosen. Or, more seriously, this is just an
3452	        // arbitrary number for now. 100k copies of this size locally takes half
3453	        // a second, so seems like a reasonably large chunk size to not hit perf
3454	        // too much by chunking but also enable time slicing.
3455	        const UNINTERRUPTABLE_CHUNK_SIZE: i64 = 128 << 20;
3456	
3457	        let mut pos = builder.cursor();
3458	        let vmctx = self.vmctx_val(&mut pos);
3459	        let pointer_type = self.pointer_type();
3460	
3461	        // Performs a raw call to the actual libcall, as dictated by the
3462	        // provided `op`. This unconditionally inserts epoch/fuel checks for all
3463	        // calls.
3464	        let raw_call =
3465	            |env: &mut FuncEnvironment<'_>, builder: &mut FunctionBuilder<'_>, op: &_| {
3466	                if env.tunables.epoch_interruption {
3467	                    env.epoch_check(builder);
3468	                }
3469	                match *op {
3470	                    BulkOp::MemoryCopy { dst, src, len } => {
3471	                        if env.tunables.consume_fuel {
3472	                            // Note that fuel is always a 64-bit counter.
3473	                            let fuel_consumed = match env.pointer_type() {
3474	                                ir::types::I32 => builder.ins().uextend(ir::types::I64, len),
3475	                                ir::types::I64 => len,
3476	                                _ => unreachable!(),
3477	                            };
3478	                            env.manual_fuel_check(builder, fuel_consumed);
3479	                        }
3480	                        let memory_copy = env.builtin_functions.memory_copy(&mut builder.func);
3481	                        builder.ins().call(memory_copy, &[vmctx, dst, src, len]);
3482	                    }
3483	                    BulkOp::MemoryFill { dst, val, len } => {
3484	                        if env.tunables.consume_fuel {
3485	                            let fuel_consumed = match env.pointer_type() {
3486	                                ir::types::I32 => builder.ins().uextend(ir::types::I64, len),
3487	                                ir::types::I64 => len,
3488	                                _ => unreachable!(),
3489	                            };
3490	                            env.manual_fuel_check(builder, fuel_consumed);
3491	                        }
3492	                        let memory_fill = env.builtin_functions.memory_fill(&mut builder.func);
3493	                        builder.ins().call(memory_fill, &[vmctx, dst, val, len]);
3494	                    }
3495	                }
3496	            };
3497	
3498	        // If epochs and fuel are disabled, then just call the libcall and
3499	        // return. No need for the loops below.
3500	        if !self.tunables.epoch_interruption && !self.tunables.consume_fuel {
