    /// Attempt to expand a copy of `len_bytes` bytes from `src_addr` to
    /// `dst_addr` inline, as a sequence of loads and stores, rather than
    /// calling the `memory_copy` libcall.
    ///
    /// This is only done for statically-known small copies: if `len_bytes` is
    /// larger than the inline threshold then this returns `false` and the
    /// caller must fall back to the libcall path. The `src_addr` and `dst_addr`
    /// values are raw host addresses that have already been bounds-checked.
    fn try_emit_inline_memory_copy(
        &mut self,
        builder: &mut FunctionBuilder<'_>,
        dst_addr: ir::Value,
        src_addr: ir::Value,
        len_bytes: u64,
    ) -> bool {
        /// The maximum number of bytes that will be copied with an inline
        /// sequence of loads and stores. Copies larger than this fall back to
        /// the `memory_copy` libcall.
        const INLINE_COPY_BYTE_THRESHOLD: u64 = 128;

        if len_bytes > INLINE_COPY_BYTE_THRESHOLD {
            return false;
        }

        // Greedily decompose the byte range into chunks, using the widest
        // available type first and working down to the narrowest. For example
        // 28 bytes becomes one `i8x16`, one `i64`, and one `i32`.
        const CHUNK_TYPES: &[ir::Type] = &[I8X16, I64, I32, I16, I8];

        let mut chunks: SmallVec<[(u32, ir::Type); 16]> = SmallVec::new();
        let mut offset: u32 = 0;
        let mut remaining = len_bytes;
        for &ty in CHUNK_TYPES {
            let size = u64::from(ty.bytes());
            while remaining >= size {
                chunks.push((offset, ty));
                offset += ty.bytes();
                remaining -= size;
            }
        }
        debug_assert_eq!(remaining, 0);

        // All accesses are explicitly little-endian. This is required for
        // correctness on big-endian targets (e.g. big-endian Pulley), where the
        // `v128` load/store instructions only encode a little-endian variant
        // and will assert if given a big-endian flag. The addresses have
        // already been bounds-checked so these accesses do not trap.
        let flags = MemFlagsData::new()
            .with_notrap()
            .with_endianness(Endianness::Little);

        // Emit all loads before any stores so that overlapping source and
        // destination ranges are copied correctly (i.e. `memmove` semantics).
        let loaded: SmallVec<[ir::Value; 16]> = chunks
            .iter()
            .map(|&(offset, ty)| {
                builder
                    .ins()
                    .load(ty, flags, src_addr, Offset32::new(offset as i32))
            })
            .collect();
        for (&(offset, _), val) in chunks.iter().zip(loaded) {
            builder
                .ins()
                .store(flags, val, dst_addr, Offset32::new(offset as i32));
        }

        true
    }

