/// If `value` is a compile-time integer constant, returns its value.
///
/// This peeks through value-preserving `uextend`/`ireduce` casts so that a
/// constant length which has been cast to the target's pointer type is still
/// recognized as a constant.
fn constant_int_value(builder: &FunctionBuilder<'_>, value: ir::Value) -> Option<i64> {
    let dfg = &builder.func.dfg;
    let inst = dfg.value_def(value).inst()?;
    match dfg.insts[inst] {
        ir::InstructionData::UnaryImm {
            opcode: ir::Opcode::Iconst,
            imm,
        } => Some(imm.bits()),
        ir::InstructionData::Unary {
            opcode: ir::Opcode::Uextend | ir::Opcode::Ireduce,
            arg,
        } => constant_int_value(builder, arg),
        _ => None,
    }
